<?php require_once __DIR__.'/../includes/bootstrap.php';$token=trim((string)($_GET['token']??$_POST['token']??''));$title='Reset Management Password';$err='';if($token==='')redirect('/auth/admin-forgot-password.php');$q=$pdo->prepare('SELECT r.*,u.username FROM admin_password_resets r JOIN users u ON u.user_id=r.user_id WHERE r.token_hash=? AND r.used_at IS NULL AND r.expires_at>=NOW() LIMIT 1');$q->execute([hash('sha256',$token)]);$r=$q->fetch();if(!$r)$err='This management reset link is invalid or expired.';if($_SERVER['REQUEST_METHOD']==='POST'&&!$err){check_csrf();$p=(string)($_POST['password']??'');$c=(string)($_POST['confirm_password']??'');if(strlen($p)<8)$err='Password must be at least 8 characters.';elseif($p!==$c)$err='Passwords do not match.';else{$pdo->prepare('UPDATE users SET password_hash=?,updated_at=NOW() WHERE user_id=?')->execute([password_hash($p,PASSWORD_DEFAULT),(int)$r['user_id']]);$pdo->prepare('UPDATE admin_password_resets SET used_at=NOW() WHERE reset_id=?')->execute([(int)$r['reset_id']]);$_SESSION['flash']=['type'=>'success','msg'=>'Management password reset successfully. Please sign in again.'];redirect('/auth/login.php');}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?></title><link rel="stylesheet" href="/assets/style.css?v=22"></head><body class="auth-body"><div class="auth-wrap"><div class="auth-card admin-auth"><img src="/assets/shadril-logo.png" style="width:72px;margin:auto;display:block" alt=""><span class="eyebrow">SECURE MANAGEMENT RESET</span><h1>Set a new password</h1><?php if($err):?><div class="errors"><?=e($err)?></div><?php if(!$r):?><a class="btn primary full" href="/auth/admin-forgot-password.php">Request a new link</a><?php endif;?><?php else:?><form method="post" class="form"><?=csrf_field()?><input type="hidden" name="token" value="<?=e($token)?>"><label>New password<input type="password" name="password" minlength="8" required></label><label>Confirm new password<input type="password" name="confirm_password" minlength="8" required></label><button class="btn dark full">Reset management password</button></form><?php endif;?></div></div></body></html>